package com.nexora.security;
import com.nexora.model.Student; import com.nexora.repository.StudentRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.core.*; import org.springframework.security.oauth2.client.authentication.OAuth2AuthenticationToken; import org.springframework.security.web.authentication.AuthenticationSuccessHandler; import org.springframework.security.web.authentication.logout.SecurityContextLogoutHandler; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.Optional;
@Component public class GoogleAuthenticationSuccessHandler implements AuthenticationSuccessHandler {private final StudentRepository repo;public GoogleAuthenticationSuccessHandler(StudentRepository r){repo=r;}public void onAuthenticationSuccess(HttpServletRequest req,HttpServletResponse res,Authentication auth)throws IOException,ServletException{if(!(auth instanceof OAuth2AuthenticationToken token)){res.sendRedirect("/login?googleError");return;}String email=token.getPrincipal().getAttribute("email");if(email==null||!email.toLowerCase().endsWith("@srmist.edu.in")){new SecurityContextLogoutHandler().logout(req,res,auth);SecurityContextHolder.clearContext();res.sendRedirect("/login?googleDenied");return;}Optional<Student> s=repo.findByLoginId(email);if(s.isEmpty()||!s.get().isActive()){new SecurityContextLogoutHandler().logout(req,res,auth);SecurityContextHolder.clearContext();res.sendRedirect("/signup?google=1");return;}res.sendRedirect("/dashboard");}}
